// Type-Safe deep get implementation:
function deepGet<T, P extends string>(obj: T, path: P): PathValue<T, P> {
  const parts = path.split('.');
  let current: any = obj;
  for (const part of parts) {
    if (current == null) return undefined as any;
    current = current[part];
  }
  return current;
}

